1	import * as esbuild from 'esbuild';
2	import { copyFileSync, mkdirSync, readFileSync, writeFileSync, existsSync } from 'fs';
3	import { resolve, dirname } from 'path';
4	import { fileURLToPath } from 'url';
5	
6	const __dirname = dirname(fileURLToPath(import.meta.url));
7	
8	// ─── Config LOCAL/self-hosted injetada em build time ─────────────────────────────
9	// Carrega o .env da raiz (darcy-local/.env) se existir; process.env tem precedência.
10	// Assim `npm run build` no widget já pega a URL/anon key configuradas, sem wrapper.
11	function loadDotEnv(p) {
12	  if (!existsSync(p)) return;
13	  for (const raw of readFileSync(p, 'utf8').split(/\r?\n/)) {
14	    const line = raw.trim();
15	    if (!line || line.startsWith('#')) continue;
16	    const eq = line.indexOf('=');
17	    if (eq === -1) continue;
18	    const key = line.slice(0, eq).trim();
19	    let val = line.slice(eq + 1).trim().replace(/^["']|["']$/g, '');
20	    if (process.env[key] === undefined) process.env[key] = val;
21	  }
22	}
23	loadDotEnv(resolve(__dirname, '../.env'));
24	
25	// Browser-facing: em produção tunelada precisa ser a URL PÚBLICA do túnel (kong/54321).
26	const SUPABASE_URL = process.env.SUPABASE_URL || 'http://127.0.0.1:54321';
27	// Anon key padrão do `supabase start` (JWT secret demo). Troque via .env se a sua diferir.
28	const SUPABASE_ANON_KEY = process.env.SUPABASE_ANON_KEY ||
29	  'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJyb2xlIjoiYW5vbiIsImlzcyI6InN1cGFiYXNlLWRlbW8iLCJpYXQiOjE2NDE3NjkyMDAsImV4cCI6MTc5OTUzNTYwMH0.dc_X5iR_VP_qT0zsiyj_I_OZ2T9FtRU2BBNWN8Bu4GE';
30	const WIDGET_ASSETS_URL = process.env.WIDGET_ASSETS_URL ||
31	  `${SUPABASE_URL}/storage/v1/object/public/widget-assets/darcy-avatar.png`;
32	const VOICE_ENABLED = (process.env.VOICE_ENABLED ?? 'true') !== 'false';
33	
34	// Custom plugin to handle CSS as inline injection
35	const inlineCSSPlugin = {
36	  name: 'inline-css',
37	  setup(build) {
38	    // Handle .css imports - return JS that injects the CSS
39	    build.onLoad({ filter: /\.css$/ }, async (args) => {
40	      const css = readFileSync(args.path, 'utf8');
41	      // Escape the CSS for embedding in JS
42	      const escapedCSS = css
43	        .replace(/\\/g, '\\\\')
44	        .replace(/`/g, '\\`')
45	        .replace(/\$/g, '\\$');
46	
47	      // Return JS code that injects the CSS immediately
48	      return {
49	        contents: `
50	                    (function() {
51	                        if (typeof document !== 'undefined' && !document.getElementById('darcy-widget-styles')) {
52	                            var style = document.createElement('style');
53	                            style.id = 'darcy-widget-styles';
54	                            style.textContent = \`${escapedCSS}\`;
55	                            document.head.appendChild(style);
56	                            console.log('[WIDGET] CSS injected');
57	                        }
58	                    })();
59	                    export default '';
60	                `,
61	        loader: 'js',
62	      };
63	    });
64	  },
65	};
66	
67	async function build() {
68	  console.log('🔨 Building widget...');
69	  console.log(`   SUPABASE_URL = ${SUPABASE_URL}`);
70	  console.log(`   VOICE_ENABLED = ${VOICE_ENABLED}`);
71	
72	  // Ensure dist directory exists
73	  mkdirSync(resolve(__dirname, 'dist'), { recursive: true });
74	
75	  // Build the JS bundle with esbuild
76	  await esbuild.build({
77	    entryPoints: [resolve(__dirname, 'src/main.tsx')],
78	    bundle: true,
79	    minify: true,
80	    format: 'iife',
81	    globalName: 'DarcyWidget',
82	    outfile: resolve(__dirname, 'dist/widget.js'),
83	    jsx: 'automatic',
84	    jsxImportSource: 'preact',
85	    define: {
86	      'process.env.NODE_ENV': '"production"',
87	      __DARCY_SUPABASE_URL__: JSON.stringify(SUPABASE_URL),
88	      __DARCY_SUPABASE_ANON_KEY__: JSON.stringify(SUPABASE_ANON_KEY),
89	      __DARCY_WIDGET_ASSETS_URL__: JSON.stringify(WIDGET_ASSETS_URL),
90	      __DARCY_VOICE_ENABLED__: String(VOICE_ENABLED),
91	    },
92	    plugins: [inlineCSSPlugin],
93	    write: true,
94	  });
95	
96	  console.log('✅ Build completed: dist/widget.js');
97	
98	  // Copy to edge function assets directory
99	  const assetsDir = resolve(__dirname, '../supabase/functions/widget-loader/assets');
100	  mkdirSync(assetsDir, { recursive: true });
101	  copyFileSync(resolve(__dirname, 'dist/widget.js'), resolve(assetsDir, 'widget.js'));
102	  console.log('📁 Copied widget.js to supabase/functions/widget-loader/assets/');
103	
104	  // Copy to storage seed dir so `supabase start`/`db reset` semeia o bucket `ativos`.
105	  const seedDir = resolve(__dirname, '../supabase/seed/ativos');
106	  mkdirSync(seedDir, { recursive: true });
107	  copyFileSync(resolve(__dirname, 'dist/widget.js'), resolve(seedDir, 'widget.js'));
108	  console.log('📁 Copied widget.js to supabase/seed/ativos/ (bucket seed)');
109	
110	  console.log('');
111	  console.log('🚀 Pronto! Se a stack já estiver rodando, re-semeie o Storage com:');
112	  console.log('   node ../scripts/upload-widget.mjs   (ou ./build-widget.ps1 / .sh)');
113	}
114	
115	build().catch(err => {
116	  console.error('❌ Build failed:', err);
117	  process.exit(1);
118	});
