1	// Cliente Supabase do dashboard. LOCAL/self-hosted: lê a URL e a anon key do .env
2	// (Vite, prefixo VITE_). Defaults = Supabase local (127.0.0.1:54321) com a anon key
3	// padrão do `supabase start`. Em produção tunelada, defina no .env:
4	//   VITE_SUPABASE_URL=https://<seu-tunnel>
5	//   VITE_SUPABASE_PUBLISHABLE_KEY=<anon key que o `supabase start` imprimiu>
6	import { createClient } from '@supabase/supabase-js';
7	import type { Database } from './types';
8	
9	const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL ?? "http://127.0.0.1:54321";
10	const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY ??
11	  "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJyb2xlIjoiYW5vbiIsImlzcyI6InN1cGFiYXNlLWRlbW8iLCJpYXQiOjE2NDE3NjkyMDAsImV4cCI6MTc5OTUzNTYwMH0.dc_X5iR_VP_qT0zsiyj_I_OZ2T9FtRU2BBNWN8Bu4GE";
12	
13	// Import the supabase client like this:
14	// import { supabase } from "@/integrations/supabase/client";
15	
16	export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
17	  auth: {
18	    storage: localStorage,
19	    persistSession: true,
20	    autoRefreshToken: true,
21	  }
22	});

1	// dashboardApi.ts
2	// Cliente do dashboard para a Edge Function autenticada `dashboard-api` (US-018).
3	//
4	// POR QUE: apos o lockdown de RLS (US-002), as tabelas de PII/analytics ficam
5	// deny-anon — a leitura direta via PostgREST com a anon key (supabase.from(...))
6	// para de funcionar. Toda leitura do dashboard passa a ir por AQUI: a function
7	// valida o access_token do Supabase Auth (Authorization: Bearer <jwt>) + checa a
8	// allowlist de e-mails e le com service_role (ver supabase/functions/dashboard-api).
9	//
10	// CONTRATO da function (POST /functions/v1/dashboard-api):
11	//   body: { resource, columns?, filters?, order?, limit? }
12	//   resposta: { data: [...] }  (200)  |  { error: ... }  (4xx/5xx)
13	//   filtros suportados: eq | neq | gte | lte | in | not_null | or
14	// O token e obtido de supabase.auth.getSession() (a sessao do login da US-017).
15	
16	import { supabase } from "@/integrations/supabase/client";
17	
18	// Mesma URL do projeto Supabase usada pelo client.ts — em sincronia via .env (Vite).
19	// Default = Supabase local; em produção tunelada defina VITE_SUPABASE_URL no .env.
20	const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL ?? "http://127.0.0.1:54321";
21	const DASHBOARD_API_URL = `${SUPABASE_URL}/functions/v1/dashboard-api`;
22	
23	// Recursos expostos pela function (allowlist espelhada do index.ts da function).
24	export type DashboardResource =
25	  | "users"
26	  | "analytics_sessions_detailed"
27	  | "analytics_interactions"
28	  | "analytics_feedback_detailed"
29	  | "analytics_question_frequency"
30	  | "analytics_abandonment_points"
31	  | "chat_sessions"
32	  | "messages"
33	  | "v_active_widgets"
34	  | "analytics_data_consent"
35	  | "analytics_data_access_logs"
36	  | "telemetry_turns"
37	  | "v_telemetry_health";
38	
39	// Operadores de filtro suportados (replicam os que os hooks usam hoje).
40	export type DashboardFilter =
41	  | { op: "eq" | "neq" | "gte" | "lte"; column: string; value: string | number | boolean }
42	  | { op: "in"; column: string; value: Array<string | number> }
43	  | { op: "not_null"; column: string }
44	  | { op: "or"; expr: string };
45	
46	export interface DashboardQuery {
47	  resource: DashboardResource;
48	  columns?: string[];
49	  filters?: DashboardFilter[];
50	  order?: { column: string; ascending?: boolean };
51	  limit?: number;
52	}
53	
54	/**
55	 * Executa uma leitura via dashboard-api e retorna as linhas (data) tipadas como T[].
56	 *
57	 * - Pega o access_token da sessao atual (supabase.auth.getSession()).
58	 * - Sem sessao -> lanca Error('not_authenticated') (o ProtectedRoute da US-017 ja
59	 *   evita montar o dashboard sem sessao, mas falhamos de forma tratavel mesmo assim).
60	 * - Erro HTTP/JSON -> lanca Error com a mensagem da function (os hooks usam react-query,
61	 *   que captura o throw e popula o `error` state — preservando o comportamento atual
62	 *   em que `if (error) throw error` propagava o erro do PostgREST).
63	 */
64	// NOTA TS: o default e `Record<string, any>` (linha de objeto), NAO `any`. Um
65	// elemento `any` faz `.reduce(cb, {} as Record<string,number>)` inferir `unknown`
66	// (quirk do TS com arrays de `any`), quebrando as agregacoes dos hooks de analytics.
67	// `Record<string, any>` mantem o acesso livre a colunas e preserva a inferencia.
68	export async function dashboardQuery<T = Record<string, any>>(query: DashboardQuery): Promise<T[]> {
69	  const { data: sessionData } = await supabase.auth.getSession();
70	  const accessToken = sessionData?.session?.access_token;
71	  if (!accessToken) {
72	    throw new Error("not_authenticated");
73	  }
74	
75	  let res: Response;
76	  try {
77	    res = await fetch(DASHBOARD_API_URL, {
78	      method: "POST",
79	      headers: {
80	        "Content-Type": "application/json",
81	        Authorization: `Bearer ${accessToken}`,
82	      },
83	      body: JSON.stringify(query),
84	    });
85	  } catch (e: any) {
86	    throw new Error(`dashboard_api_network_error: ${e?.message || e}`);
87	  }
88	
89	  let body: any = null;
90	  try {
91	    body = await res.json();
92	  } catch {
93	    body = null;
94	  }
95	
96	  if (!res.ok) {
97	    const detail = body?.error || res.statusText || `HTTP ${res.status}`;
98	    throw new Error(`dashboard_api_error: ${detail}`);
99	  }
100	
101	  const rows = body?.data;
102	  return (Array.isArray(rows) ? rows : []) as T[];
103	}
104

1	const corsHeaders = {
2	  'Access-Control-Allow-Origin': '*',
3	  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
4	};
5	
6	// Cache-bust: increment version when widget changes
7	const WIDGET_VERSION = '20260526-v27-voice-continuity';
8	// LOCAL/self-hosted: busca o widget.js do Storage via a URL INTERNA do Supabase
9	// (SUPABASE_URL é injetada automaticamente no runtime das edge functions). Funciona
10	// igual no cloud e no local sem hardcode de projeto — é fetch server->storage.
11	const SUPABASE_URL = Deno.env.get('SUPABASE_URL') ?? 'http://127.0.0.1:54321';
12	const WIDGET_URL = `${SUPABASE_URL}/storage/v1/object/public/ativos/widget.js?v=${WIDGET_VERSION}`;
13	
14	let cachedWidget: string | null = null;
15	let cacheTime: number = 0;
16	const CACHE_DURATION = 2 * 60 * 1000; // 2 minutes server cache
17	
18	Deno.serve(async (req) => {
19	  if (req.method === 'OPTIONS') {
20	    return new Response(null, { headers: corsHeaders });
21	  }
22	
23	  try {
24	    const now = Date.now();
25	
26	    if (!cachedWidget || (now - cacheTime) > CACHE_DURATION) {
27	      const response = await fetch(WIDGET_URL);
28	      if (!response.ok) {
29	        throw new Error(`Failed to fetch widget: ${response.status}`);
30	      }
31	      cachedWidget = await response.text();
32	      cacheTime = now;
33	    }
34	
35	    return new Response(cachedWidget, {
36	      headers: {
37	        ...corsHeaders,
38	        'Content-Type': 'text/javascript; charset=utf-8',
39	        'Cache-Control': 'public, max-age=120', // 2 min browser cache
40	        'ETag': `"${WIDGET_VERSION}"`,
41	      },
42	    });
43	  } catch (error) {
44	    console.error('[widget-loader] Error:', error);
45	    return new Response('', {
46	      status: 500,
47	      headers: { ...corsHeaders, 'Content-Type': 'text/javascript' },
48	    });
49	  }
50	});
